package escuela.sitioweb;

import escuela.seguridad.service.UsuarioPrincipal;
import escuela.common.exception.ReglaNegocioException;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.bind.WebDataBinder;
import jakarta.servlet.http.HttpServletResponse;
import java.util.*;
import static escuela.sitioweb.SitioExtras.*;

@Controller @RequiredArgsConstructor @RequestMapping("/admin/diseno-web")
public class SitioCatalogosController {
    private final SitioService sitios;
    private final SitioCatalogosService catalogos;
    public record Fila(String id,String titulo,String detalle,int orden,boolean activo,String motivo,String editar,String fotos,String imagen) {}
    @InitBinder("item") void campos(WebDataBinder b){Object target=b.getTarget();if(target instanceof Album)b.setAllowedFields("titulo","descripcion","orden","activo","motivoRetiro");else if(target instanceof Foto)b.setAllowedFields("imagenId","descripcion","orden","activo","motivoRetiro");else if(target instanceof Ubicacion)b.setAllowedFields("plantelId","nombre","direccion","horario","telefono","orden","activo","motivoRetiro");else if(target instanceof Contacto)b.setAllowedFields("telefono","correo","whatsappActivo","whatsapp","mensaje","privacidad");}
    private String origen(String base,String q,String estado,int pagina){return org.springframework.web.util.UriComponentsBuilder.fromPath(base).queryParam("q",q).queryParam("estado",estado).queryParam("pagina",Math.max(0,pagina)).build().encode().toUriString();}
    private List<Fila> filas(UsuarioPrincipal p,String tipo,String album){var f=sitios.borrador(p);if(tipo.equals("album"))return f.getExtras().getAlbumes().stream().map(a->new Fila(a.getId(),a.getTitulo(),a.getDescripcion(),a.getOrden(),a.isActivo(),a.getMotivoRetiro(),"/admin/diseno-web/galeria/"+a.getId()+"/editar","/admin/diseno-web/galeria/"+a.getId()+"/fotos",null)).toList();if(tipo.equals("foto"))return catalogos.album(p,album).getFotos().stream().map(a->new Fila(a.getId(),a.getDescripcion(),"Imagen #"+a.getImagenId(),a.getOrden(),a.isActivo(),a.getMotivoRetiro(),"/admin/diseno-web/galeria/"+album+"/fotos/"+a.getId()+"/editar",null,"/admin/diseno-web/imagenes/"+a.getImagenId())).toList();return f.getExtras().getUbicaciones().stream().map(a->new Fila(a.getId(),a.getNombre(),a.getDireccion()+" · "+a.getHorario(),a.getOrden(),a.isActivo(),a.getMotivoRetiro(),"/admin/diseno-web/ubicaciones/"+a.getId()+"/editar",null,null)).toList();}
    private List<Fila> filtrar(List<Fila> filas,String q,String estado){var texto=q.strip().toLowerCase(Locale.ROOT);return filas.stream().filter(f->((f.titulo()+" "+f.detalle()).toLowerCase(Locale.ROOT).contains(texto))).filter(f->!estado.equals("ACTIVO")&&!estado.equals("RETIRADO")||f.activo()==estado.equals("ACTIVO")).sorted(Comparator.comparingInt(Fila::orden).thenComparing(Fila::id)).toList();}
    private String listado(UsuarioPrincipal p,Model m,String tipo,String album,String q,String estado,int pagina){var base=tipo.equals("album")?"/admin/diseno-web/galeria":tipo.equals("foto")?"/admin/diseno-web/galeria/"+album+"/fotos":"/admin/diseno-web/ubicaciones";var resultado=filtrar(filas(p,tipo,album),q,estado);int paginas=Math.max(1,(resultado.size()+19)/20),actual=Math.max(0,Math.min(pagina,paginas-1));m.addAttribute("filas",resultado.stream().skip(actual*20L).limit(20).toList());m.addAttribute("total",resultado.size());m.addAttribute("paginas",paginas);m.addAttribute("pagina",actual);m.addAttribute("q",q);m.addAttribute("estado",estado);m.addAttribute("base",base);m.addAttribute("tipo",tipo);m.addAttribute("origen",origen(base,q,estado,actual));m.addAttribute("anterior",origen(base,q,estado,actual-1)+"#resultados");m.addAttribute("siguiente",origen(base,q,estado,actual+1)+"#resultados");m.addAttribute("titulo",tipo.equals("album")?"Álbumes de la escuela":tipo.equals("foto")?"Fotografías · "+catalogos.album(p,album).getTitulo():"Ubicaciones públicas");return "admin/sitio-catalogo";}
    @GetMapping("/galeria") String albumes(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){return listado(p,m,"album",null,q,estado,pagina);}
    @GetMapping("/galeria/{album}/fotos") String fotos(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@PathVariable String album,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){return listado(p,m,"foto",album,q,estado,pagina);}
    @GetMapping("/ubicaciones") String ubicaciones(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){return listado(p,m,"ubicacion",null,q,estado,pagina);}
    private String formulario(UsuarioPrincipal p,Model m,String tipo,Object item,String base,String accion,String q,String estado,int pagina,Long version){m.addAttribute("item",item);m.addAttribute("tipo",tipo);m.addAttribute("accion",accion);m.addAttribute("origen",origen(base,q,estado,pagina)+"#resultados");m.addAttribute("q",q);m.addAttribute("estado",estado);m.addAttribute("pagina",pagina);m.addAttribute("version",version==null?sitios.borrador(p).getVersion():version);m.addAttribute("imagenes",sitios.imagenes(p));m.addAttribute("planteles",catalogos.planteles(p));m.addAttribute("titulo",tipo.equals("album")?"Capturar álbum":tipo.equals("foto")?"Capturar fotografía":tipo.equals("contacto")?"Contacto y WhatsApp":"Capturar ubicación");return "admin/sitio-catalogo-form";}
    @GetMapping({"/galeria/nuevo","/galeria/{id}/editar"}) String albumForm(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@PathVariable(required=false)String id,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){return formulario(p,m,"album",id==null?new Album():catalogos.album(p,id),"/admin/diseno-web/galeria",id==null?"/admin/diseno-web/galeria/nuevo":"/admin/diseno-web/galeria/"+id+"/editar",q,estado,pagina,null);}
    @PostMapping({"/galeria/nuevo","/galeria/{id}/editar"}) String albumGuardar(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@PathVariable(required=false)String id,@Valid @ModelAttribute("item")Album item,BindingResult errors,@RequestParam long version,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){if(!errors.hasErrors())try{catalogos.guardarAlbum(p,id,item,version);return "redirect:"+origen("/admin/diseno-web/galeria",q,estado,pagina)+"#resultados";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}return formulario(p,m,"album",item,"/admin/diseno-web/galeria",id==null?"/admin/diseno-web/galeria/nuevo":"/admin/diseno-web/galeria/"+id+"/editar",q,estado,pagina,version);}
    @GetMapping({"/galeria/{album}/fotos/nueva","/galeria/{album}/fotos/{id}/editar"}) String fotoForm(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@PathVariable String album,@PathVariable(required=false)String id,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){catalogos.album(p,album);String base="/admin/diseno-web/galeria/"+album+"/fotos";return formulario(p,m,"foto",id==null?new Foto():catalogos.foto(p,album,id),base,base+(id==null?"/nueva":"/"+id+"/editar"),q,estado,pagina,null);}
    @PostMapping({"/galeria/{album}/fotos/nueva","/galeria/{album}/fotos/{id}/editar"}) String fotoGuardar(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@PathVariable String album,@PathVariable(required=false)String id,@Valid @ModelAttribute("item")Foto item,BindingResult errors,@RequestParam long version,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){String base="/admin/diseno-web/galeria/"+album+"/fotos";if(!errors.hasErrors())try{catalogos.guardarFoto(p,album,id,item,version);return "redirect:"+origen(base,q,estado,pagina)+"#resultados";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}return formulario(p,m,"foto",item,base,base+(id==null?"/nueva":"/"+id+"/editar"),q,estado,pagina,version);}
    @GetMapping({"/ubicaciones/nueva","/ubicaciones/{id}/editar"}) String ubicacionForm(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@PathVariable(required=false)String id,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){return formulario(p,m,"ubicacion",id==null?new Ubicacion():catalogos.ubicacion(p,id),"/admin/diseno-web/ubicaciones",id==null?"/admin/diseno-web/ubicaciones/nueva":"/admin/diseno-web/ubicaciones/"+id+"/editar",q,estado,pagina,null);}
    @PostMapping({"/ubicaciones/nueva","/ubicaciones/{id}/editar"}) String ubicacionGuardar(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@PathVariable(required=false)String id,@Valid @ModelAttribute("item")Ubicacion item,BindingResult errors,@RequestParam long version,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina){if(!errors.hasErrors())try{catalogos.guardarUbicacion(p,id,item,version);return "redirect:"+origen("/admin/diseno-web/ubicaciones",q,estado,pagina)+"#resultados";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}return formulario(p,m,"ubicacion",item,"/admin/diseno-web/ubicaciones",id==null?"/admin/diseno-web/ubicaciones/nueva":"/admin/diseno-web/ubicaciones/"+id+"/editar",q,estado,pagina,version);}
    @GetMapping("/contacto") String contacto(@AuthenticationPrincipal UsuarioPrincipal p,Model m){var f=sitios.borrador(p);return formulario(p,m,"contacto",f.getExtras().getContacto(),"/admin/diseno-web","/admin/diseno-web/contacto","","TODOS",0,f.getVersion());}
    @PostMapping("/contacto") String contactoGuardar(@AuthenticationPrincipal UsuarioPrincipal p,Model m,@Valid @ModelAttribute("item")Contacto item,BindingResult errors,@RequestParam long version){if(!errors.hasErrors())try{catalogos.guardarContacto(p,item,version);return "redirect:/admin/diseno-web?guardado";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}return formulario(p,m,"contacto",item,"/admin/diseno-web","/admin/diseno-web/contacto","","TODOS",0,version);}
    @GetMapping({"/galeria/excel","/galeria/{album}/fotos/excel","/ubicaciones/excel"}) void excel(@AuthenticationPrincipal UsuarioPrincipal p,@PathVariable(required=false)String album,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,jakarta.servlet.http.HttpServletRequest request,HttpServletResponse response)throws java.io.IOException{String tipo=album!=null?"foto":request.getRequestURI().contains("ubicaciones")?"ubicacion":"album";var filas=filtrar(filas(p,tipo,album),q,estado);try(var book=new org.apache.poi.xssf.usermodel.XSSFWorkbook()){var sheet=book.createSheet("Contenido del sitio");var header=sheet.createRow(0);String[] nombres={"Nombre o descripción","Detalle","Orden","Estado","Motivo de retiro"};for(int i=0;i<nombres.length;i++)header.createCell(i).setCellValue(nombres[i]);int n=1;for(var f:filas){var r=sheet.createRow(n++);r.createCell(0).setCellValue(f.titulo());r.createCell(1).setCellValue(f.detalle());r.createCell(2).setCellValue(f.orden());r.createCell(3).setCellValue(f.activo()?"Activo":"Retirado");r.createCell(4).setCellValue(f.motivo()==null?"":f.motivo());}for(int i=0;i<5;i++)sheet.setColumnWidth(i,(i==1||i==4?55:30)*256);sheet.createFreezePane(0,1);response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");response.setHeader("Content-Disposition","attachment; filename=contenido-sitio.xlsx");book.write(response.getOutputStream());}}
}
